-- Migration: add local_print_token column to store_print_settings
--
-- Purpose: pairs a store with an optional locally-installed Windows helper app
-- (UdcPrintService.exe, downloads/UdcPrintService.exe) that can enumerate the
-- computer's ACTUAL installed printers and print silently to them via
-- WebView2 -- see chat discussion for why a website itself cannot do this.
--
-- The token is generated by the helper app on first run (shown via its tray
-- icon's "Copy Setup Token") and pasted in here once per computer/store. It
-- is sent back as a header on every /print request so the helper only
-- accepts jobs that were paired by someone with real physical/admin access
-- to that till PC, not just anyone who can reach this website.
--
-- SAFETY: ADD COLUMN IF NOT EXISTS -- additive only, safe to run more than
-- once, does not touch any other column, does not drop/recreate the table.

ALTER TABLE store_print_settings
  ADD COLUMN IF NOT EXISTS local_print_token VARCHAR(64) NULL DEFAULT NULL AFTER delivery_printer_name;
